mkdir -p /workspace/klee-analysis && cat > /workspace/klee-analysis/curl_fnmatch_standalone.c << 'ENDOFFILE'
/* Standalone version of curl's Curl_fnmatch for KLEE symbolic execution analysis.
   Extracted from curl/lib/curl_fnmatch.c with necessary type macros. */

#include <stddef.h>
#include <string.h>

/* Boolean type */
typedef unsigned int bool;
#define TRUE 1
#define FALSE 0

/* Character type macros from curl/lib/curl_ctype.h */
#define ISLOWHEXALPHA(x) (((x) >= 'a') && ((x) <= 'f'))
#define ISUPHEXALPHA(x)  (((x) >= 'A') && ((x) <= 'F'))
#define ISLOWCNTRL(x) ((unsigned char)(x) <= 0x1f)
#define IS7F(x)       ((x) == 0x7f)
#define ISLOWPRINT(x) (((x) >= 9) && ((x) <= 0x0d))
#define ISPRINT(x)  (ISLOWPRINT(x) || (((x) >= ' ') && ((x) <= 0x7e)))
#define ISGRAPH(x)  (ISLOWPRINT(x) || (((x) > ' ') && ((x) <= 0x7e)))
#define ISCNTRL(x)  (ISLOWCNTRL(x) || IS7F(x))
#define ISALPHA(x)  (ISLOWER(x) || ISUPPER(x))
#define ISXDIGIT(x) (ISDIGIT(x) || ISLOWHEXALPHA(x) || ISUPHEXALPHA(x))
#define ISODIGIT(x) (((x) >= '0') && ((x) <= '7'))
#define ISALNUM(x)  (ISDIGIT(x) || ISLOWER(x) || ISUPPER(x))
#define ISUPPER(x)  (((x) >= 'A') && ((x) <= 'Z'))
#define ISLOWER(x)  (((x) >= 'a') && ((x) <= 'z'))
#define ISDIGIT(x)  (((x) >= '0') && ((x) <= '9'))
#define ISBLANK(x)  (((x) == ' ') || ((x) == '\t'))
#define ISSPACE(x)  (ISBLANK(x) || (((x) >= 0xa) && ((x) <= 0x0d)))

/* Constants from curl_fnmatch.h */
#define CURL_FNMATCH_MATCH    0
#define CURL_FNMATCH_NOMATCH  1
#define CURL_FNMATCH_FAIL     2

/* Constants from curl_fnmatch.c */
#define CURLFNM_CHARSET_LEN (sizeof(char) * 256)
#define CURLFNM_CHSET_SIZE (CURLFNM_CHARSET_LEN + 15)
#define CURLFNM_NEGATE  CURLFNM_CHARSET_LEN
#define CURLFNM_ALNUM   (CURLFNM_CHARSET_LEN + 1)
#define CURLFNM_DIGIT   (CURLFNM_CHARSET_LEN + 2)
#define CURLFNM_XDIGIT  (CURLFNM_CHARSET_LEN + 3)
#define CURLFNM_ALPHA   (CURLFNM_CHARSET_LEN + 4)
#define CURLFNM_PRINT   (CURLFNM_CHARSET_LEN + 5)
#define CURLFNM_BLANK   (CURLFNM_CHARSET_LEN + 6)
#define CURLFNM_LOWER   (CURLFNM_CHARSET_LEN + 7)
#define CURLFNM_GRAPH   (CURLFNM_CHARSET_LEN + 8)
#define CURLFNM_SPACE   (CURLFNM_CHARSET_LEN + 9)
#define CURLFNM_UPPER   (CURLFNM_CHARSET_LEN + 10)

typedef enum {
  CURLFNM_SCHS_DEFAULT = 0,
  CURLFNM_SCHS_RIGHTBR,
  CURLFNM_SCHS_RIGHTBRLEFTBR
} setcharset_state;

typedef enum {
  CURLFNM_PKW_INIT = 0,
  CURLFNM_PKW_DDOT
} parsekey_state;

typedef enum {
  CCLASS_OTHER = 0,
  CCLASS_DIGIT,
  CCLASS_UPPER,
  CCLASS_LOWER
} char_class;

#define SETCHARSET_OK     1
#define SETCHARSET_FAIL   0

static int parsekeyword(const unsigned char **pattern, unsigned char *charset)
{
  parsekey_state state = CURLFNM_PKW_INIT;
  char keyword[10] = { 0 };
  size_t i;
  const unsigned char *p = *pattern;
  bool found = FALSE;
  for(i = 0; !found; i++) {
    char c = (char)*p++;
    if(i >= sizeof(keyword))
      return SETCHARSET_FAIL;
    switch(state) {
    case CURLFNM_PKW_INIT:
      if(ISLOWER(c))
        keyword[i] = c;
      else if(c == ':')
        state = CURLFNM_PKW_DDOT;
      else
        return SETCHARSET_FAIL;
      break;
    case CURLFNM_PKW_DDOT:
      if(c == ']')
        found = TRUE;
      else
        return SETCHARSET_FAIL;
    }
  }

  *pattern = p;
  if(!strcmp(keyword, "digit"))
    charset[CURLFNM_DIGIT] = 1;
  else if(!strcmp(keyword, "alnum"))
    charset[CURLFNM_ALNUM] = 1;
  else if(!strcmp(keyword, "alpha"))
    charset[CURLFNM_ALPHA] = 1;
  else if(!strcmp(keyword, "xdigit"))
    charset[CURLFNM_XDIGIT] = 1;
  else if(!strcmp(keyword, "print"))
    charset[CURLFNM_PRINT] = 1;
  else if(!strcmp(keyword, "graph"))
    charset[CURLFNM_GRAPH] = 1;
  else if(!strcmp(keyword, "space"))
    charset[CURLFNM_SPACE] = 1;
  else if(!strcmp(keyword, "blank"))
    charset[CURLFNM_BLANK] = 1;
  else if(!strcmp(keyword, "upper"))
    charset[CURLFNM_UPPER] = 1;
  else if(!strcmp(keyword, "lower"))
    charset[CURLFNM_LOWER] = 1;
  else
    return SETCHARSET_FAIL;
  return SETCHARSET_OK;
}

static char_class charclass(unsigned char c)
{
  if(ISUPPER(c))
    return CCLASS_UPPER;
  if(ISLOWER(c))
    return CCLASS_LOWER;
  if(ISDIGIT(c))
    return CCLASS_DIGIT;
  return CCLASS_OTHER;
}

static void setcharorrange(const unsigned char **pp, unsigned char *charset)
{
  const unsigned char *p = (*pp)++;
  unsigned char c = *p++;

  charset[c] = 1;
  if(ISALNUM(c) && *p++ == '-') {
    char_class cc = charclass(c);
    unsigned char endrange = *p++;

    if(endrange == '\\')
      endrange = *p++;
    if(endrange >= c && charclass(endrange) == cc) {
      while(c++ != endrange)
        if(charclass(c) == cc)
          charset[c] = 1;
      *pp = p;
    }
  }
}

static int setcharset(const unsigned char **p, unsigned char *charset)
{
  setcharset_state state = CURLFNM_SCHS_DEFAULT;
  bool something_found = FALSE;
  unsigned char c;

  memset(charset, 0, CURLFNM_CHSET_SIZE);
  for(;;) {
    c = **p;
    if(!c)
      return SETCHARSET_FAIL;

    switch(state) {
    case CURLFNM_SCHS_DEFAULT:
      if(c == ']') {
        if(something_found)
          return SETCHARSET_OK;
        something_found = TRUE;
        state = CURLFNM_SCHS_RIGHTBR;
        charset[c] = 1;
        (*p)++;
      }
      else if(c == '[') {
        const unsigned char *pp = *p + 1;
        if(parsekeyword(&pp, charset)) {
          *p = pp;
          something_found = TRUE;
        }
        else {
          charset[c] = 1;
          something_found = TRUE;
          (*p)++;
        }
      }
      else if(c == '^' || c == '!') {
        if(!something_found) {
          if(charset[CURLFNM_NEGATE]) {
            charset[c] = 1;
            something_found = TRUE;
          }
          else
            charset[CURLFNM_NEGATE] = 1;
        }
        else
          charset[c] = 1;
        (*p)++;
      }
      else if(c == '\\') {
        c = *(++(*p));
        if(c)
          setcharorrange(p, charset);
        else
          charset['\\'] = 1;
        something_found = TRUE;
      }
      else {
        setcharorrange(p, charset);
        something_found = TRUE;
      }
      break;
    case CURLFNM_SCHS_RIGHTBR:
      if(c == '[') {
        state = CURLFNM_SCHS_RIGHTBRLEFTBR;
        charset[c] = 1;
        (*p)++;
      }
      else if(c == ']') {
        return SETCHARSET_OK;
      }
      else if(ISPRINT(c)) {
        charset[c] = 1;
        (*p)++;
        state = CURLFNM_SCHS_DEFAULT;
      }
      else
        goto fail;
      break;
    case CURLFNM_SCHS_RIGHTBRLEFTBR:
      if(c == ']')
        return SETCHARSET_OK;
      state = CURLFNM_SCHS_DEFAULT;
      charset[c] = 1;
      (*p)++;
      break;
    }
  }
fail:
  return SETCHARSET_FAIL;
}

static int loop(const unsigned char *pattern, const unsigned char *string,
                int maxstars)
{
  const unsigned char *p = pattern;
  const unsigned char *s = string;
  unsigned char charset[CURLFNM_CHSET_SIZE] = { 0 };

  for(;;) {
    const unsigned char *pp;

    switch(*p) {
    case '*':
      if(!maxstars)
        return CURL_FNMATCH_NOMATCH;
      for(;;) {
        if(*++p == '\0')
          return CURL_FNMATCH_MATCH;
        if(*p == '?') {
          if(!*s++)
            return CURL_FNMATCH_NOMATCH;
        }
        else if(*p != '*')
          break;
      }
      for(maxstars--; *s; s++) {
        if(loop(p, s, maxstars) == CURL_FNMATCH_MATCH)
          return CURL_FNMATCH_MATCH;
      }
      return CURL_FNMATCH_NOMATCH;
    case '?':
      if(!*s)
        return CURL_FNMATCH_NOMATCH;
      s++;
      p++;
      break;
    case '\0':
      return *s ? CURL_FNMATCH_NOMATCH : CURL_FNMATCH_MATCH;
    case '\\':
      if(p[1])
        p++;
      if(*s++ != *p++)
        return CURL_FNMATCH_NOMATCH;
      break;
    case '[':
      pp = p + 1;
      if(setcharset(&pp, charset)) {
        bool found = FALSE;
        if(!*s)
          return CURL_FNMATCH_NOMATCH;
        if(charset[(unsigned int)*s])
          found = TRUE;
        else if(charset[CURLFNM_ALNUM])
          found = ISALNUM(*s);
        else if(charset[CURLFNM_ALPHA])
          found = ISALPHA(*s);
        else if(charset[CURLFNM_DIGIT])
          found = ISDIGIT(*s);
        else if(charset[CURLFNM_XDIGIT])
          found = ISXDIGIT(*s);
        else if(charset[CURLFNM_PRINT])
          found = ISPRINT(*s);
        else if(charset[CURLFNM_SPACE])
          found = ISBLANK(*s);
        else if(charset[CURLFNM_UPPER])
          found = ISUPPER(*s);
        else if(charset[CURLFNM_LOWER])
          found = ISLOWER(*s);
        else if(charset[CURLFNM_BLANK])
          found = ISBLANK(*s);
        else if(charset[CURLFNM_GRAPH])
          found = ISGRAPH(*s);

        if(charset[CURLFNM_NEGATE])
          found = !found;

        if(!found)
          return CURL_FNMATCH_NOMATCH;
        p = pp + 1;
        s++;
        break;
      }
      return CURL_FNMATCH_NOMATCH;

    default:
      if(*p++ != *s++)
        return CURL_FNMATCH_NOMATCH;
      break;
    }
  }
}

int Curl_fnmatch(void *ptr, const char *pattern, const char *string)
{
  (void)ptr;
  if(!pattern || !string) {
    return CURL_FNMATCH_FAIL;
  }
  return loop((const unsigned char *)pattern,
              (const unsigned char *)string, 2);
}
ENDOFFILE
echo "Created standalone curl_fnmatch.c" && wc -l /workspace/klee-analysis/curl_fnmatch_standalone.c

cat > /workspace/klee-analysis/harness_fnmatch.c << 'ENDOFFILE'
/* KLEE harness for Curl_fnmatch symbolic execution analysis.
   This harness creates symbolic pattern and string inputs, then calls
   Curl_fnmatch to explore different execution paths. */

#include <stddef.h>
#include <stdint.h>
#include <string.h>

/* KLEE symbolic execution headers */
#include <klee/klee.h>

/* Function prototype from curl_fnmatch.h */
int Curl_fnmatch(void *ptr, const char *pattern, const char *string);

/* Define constants for result interpretation */
#define CURL_FNMATCH_MATCH    0
#define CURL_FNMATCH_NOMATCH  1
#define CURL_FNMATCH_FAIL     2

/* Maximum input sizes */
#define MAX_PATTERN_LEN  8
#define MAX_STRING_LEN   8

int main() {
    char pattern[MAX_PATTERN_LEN + 1];
    char string[MAX_STRING_LEN + 1];

    /* Make pattern and string symbolic */
    klee_make_symbolic(pattern, sizeof(pattern), "pattern");
    klee_make_symbolic(string, sizeof(string), "string");

    /* Constrain to printable ASCII + null terminator for meaningful analysis */
    int i;
    for (i = 0; i < MAX_PATTERN_LEN; i++) {
        /* Allow null bytes or printable ASCII (32-126) */
        klee_assume(pattern[i] == 0 || (pattern[i] >= 32 && pattern[i] <= 126));
    }
    /* Ensure null-terminated */
    klee_assume(pattern[MAX_PATTERN_LEN] == 0);

    for (i = 0; i < MAX_STRING_LEN; i++) {
        klee_assume(string[i] == 0 || (string[i] >= 32 && string[i] <= 126));
    }
    klee_assume(string[MAX_STRING_LEN] == 0);

    /* Call the function under analysis */
    int result = Curl_fnmatch(NULL, pattern, string);

    /* Report results */
    if (result == CURL_FNMATCH_MATCH) {
        /* Pattern matched string */
    } else if (result == CURL_FNMATCH_NOMATCH) {
        /* Pattern did not match string */
    } else {
        /* CURL_FNMATCH_FAIL - either NULL pointer was passed */
    }

    return result;
}
ENDOFFILE
echo "Created KLEE harness" && wc -l /workspace/klee-analysis/harness_fnmatch.c

cat > /workspace/klee-analysis/curl_url_standalone.c << 'ENDOFFILE'
/* Standalone version of curl's Curl_is_absolute_url and Curl_junkscan
   for KLEE symbolic execution analysis.
   Extracted from curl/lib/urlapi.c with necessary dependencies. */

#include <stddef.h>
#include <string.h>
#include <stdint.h>

/* Character type macros from curl/lib/curl_ctype.h */
#define ISLOWHEXALPHA(x) (((x) >= 'a') && ((x) <= 'f'))
#define ISUPHEXALPHA(x)  (((x) >= 'A') && ((x) <= 'F'))
#define ISALPHA(x)  (((x) >= 'a' && (x) <= 'z') || ((x) >= 'A' && (x) <= 'Z'))
#define ISXDIGIT(x) (((x) >= '0' && (x) <= '9') || ISLOWHEXALPHA(x) || ISUPHEXALPHA(x))
#define ISALNUM(x)  (ISALPHA(x) || ((x) >= '0' && (x) <= '9'))
#define ISUPPER(x)  (((x) >= 'A') && ((x) <= 'Z'))
#define ISLOWER(x)  (((x) >= 'a') && ((x) <= 'z'))
#define ISDIGIT(x)  (((x) >= '0') && ((x) <= '9'))
#define ISBLANK(x)  (((x) == ' ') || ((x) == '\t'))

/* Constants from urlapi.c */
#define MAX_SCHEME_LEN 64
#define CURL_MAX_INPUT_LENGTH 8000000

/* Return codes */
#define CURLUE_OK 0
#define CURLUE_MALFORMED_INPUT 5

/* Curl_strntolower - converts string to lowercase */
static char *Curl_strntolower(char *dest, const char *src, size_t n) {
    size_t i;
    for (i = 0; i < n; i++) {
        char c = src[i];
        if (c >= 'A' && c <= 'Z')
            dest[i] = c + 32;
        else
            dest[i] = c;
    }
    return dest;
}

/* Check for drive prefix (simplified, only for non-Windows) */
#define STARTS_WITH_DRIVE_PREFIX(url) (0)

/* Curl_is_absolute_url - extracted from curl/lib/urlapi.c */
size_t Curl_is_absolute_url(const char *url, char *buf, size_t buflen,
                            int guess_scheme)
{
  size_t i = 0;
  if(buf)
    buf[0] = 0;

  if(guess_scheme && STARTS_WITH_DRIVE_PREFIX(url))
    return 0;

  if(ISALPHA(url[0]))
    for(i = 1; i < MAX_SCHEME_LEN; ++i) {
      char s = url[i];
      if(s && (ISALNUM(s) || (s == '+') || (s == '-') || (s == '.'))) {
        /* scheme character */
      }
      else {
        break;
      }
    }
  if(i && (url[i] == ':') && ((url[i + 1] == '/') || !guess_scheme)) {
    size_t len = i;
    if(buf) {
      Curl_strntolower(buf, url, i);
      buf[i] = 0;
    }
    return len;
  }
  return 0;
}

/* Curl_junkscan - extracted from curl/lib/urlapi.c */
int Curl_junkscan(const char *url, size_t *urllen, int allowspace)
{
  size_t n = strlen(url);
  size_t i;
  unsigned char control;
  const unsigned char *p = (const unsigned char *)url;
  if(n > CURL_MAX_INPUT_LENGTH)
    return CURLUE_MALFORMED_INPUT;

  control = allowspace ? 0x1f : 0x20;
  for(i = 0; i < n; i++) {
    if(p[i] <= control || p[i] == 127)
      return CURLUE_MALFORMED_INPUT;
  }
  *urllen = n;
  return CURLUE_OK;
}
ENDOFFILE
echo "Created url standalone" && wc -l /workspace/klee-analysis/curl_url_standalone.c

cat > /workspace/klee-analysis/harness_url.c << 'ENDOFFILE'
/* KLEE harness for Curl_is_absolute_url and Curl_junkscan
   symbolic execution analysis. */

#include <stddef.h>
#include <stdint.h>
#include <string.h>

#include <klee/klee.h>

/* Function prototypes */
size_t Curl_is_absolute_url(const char *url, char *buf, size_t buflen, int guess_scheme);
int Curl_junkscan(const char *url, size_t *urllen, int allowspace);

#define MAX_URL_LEN 16
#define MAX_SCHEME_LEN 64
#define CURLUE_OK 0
#define CURLUE_MALFORMED_INPUT 5

int main() {
    char url[MAX_URL_LEN + 1];
    char buf[MAX_SCHEME_LEN + 1];
    size_t urllen = 0;
    int guess_scheme;
    int allowspace;

    /* Make inputs symbolic */
    klee_make_symbolic(url, sizeof(url), "url");
    klee_make_symbolic(&guess_scheme, sizeof(guess_scheme), "guess_scheme");
    klee_make_symbolic(&allowspace, sizeof(allowspace), "allowspace");

    /* Constrain URL to printable ASCII + null */
    int i;
    for (i = 0; i < MAX_URL_LEN; i++) {
        klee_assume(url[i] == 0 || (url[i] >= 32 && url[i] <= 126));
    }
    klee_assume(url[MAX_URL_LEN] == 0);

    /* Constrain booleans */
    klee_assume(guess_scheme == 0 || guess_scheme == 1);
    klee_assume(allowspace == 0 || allowspace == 1);

    /* Test 1: Curl_junkscan */
    int junkscan_result = Curl_junkscan(url, &urllen, allowspace);
    if (junkscan_result == CURLUE_OK) {
        /* URL passed junk scan - urllen contains the length */
    } else {
        /* URL failed junk scan - contains control characters */
    }

    /* Test 2: Curl_is_absolute_url */
    memset(buf, 0, sizeof(buf));
    size_t scheme_len = Curl_is_absolute_url(url, buf, sizeof(buf), guess_scheme);
    if (scheme_len > 0) {
        /* URL has an absolute scheme (e.g., http:, ftp:) */
    } else {
        /* URL is not absolute or doesn't have a valid scheme */
    }

    return 0;
}
ENDOFFILE
echo "Created URL harness" && wc -l /workspace/klee-analysis/harness_url.c

model.observation_template:
{% if output.exception_info -%}
<exception>{{output.exception_info}}</exception>
{% endif -%}
<returncode>{{output.returncode}}</returncode>
{% if output.output | length < 10000 -%}
<output>
{{ output.output -}}
</output>
{%- else -%}
<warning>
The output of your last command was too long.
Please try a different command that produces less output.
If you really need to see something from the full command's output, redirect output to a file and inspect it selectively.
</warning>
{%- set elided_chars = output.output | length - 10000 -%}
<output_head>
{{ output.output[:5000] }}
</output_head>
<elided_chars>
{{ elided_chars }} characters elided
</elided_chars>
<output_tail>
{{ output.output[-5000:] }}
</output_tail>
{%- endif -%}

